  "Alle Merkmale": "Todas las características",
  "Festpreis nach dem Erstgespräch.": "Precio cerrado tras la primera conversación.",
  "Bei jeder Leistung dabei": "Incluido en cada servicio",
  "Monatlicher Bericht": "Informe mensual",
  "Änderungen inklusive": "Cambios incluidos",
  "Keine Einarbeitung": "Sin curva de aprendizaje",
  "Was das heisst": "Qué significa",
  "Wer Ihren Agent baut, betreut ihn auch.": "Quien construye su agente también lo mantiene.",
  "AVV, EU-Verarbeitung, wo verfügbar, Löschfristen nach Ihrer Vorgabe.": "DPA, tratamiento en la UE cuando está disponible y plazos de conservación según sus indicaciones.",
  "Anfragen, Buchungen und gesparte Zeit auf einer Seite.": "Consultas, reservas y tiempo ahorrado en una sola página.",
  "Kleine Anpassungen meist am selben Tag.": "Pequeños ajustes, normalmente el mismo día.",
  "Sie bekommen einen fertigen Agent, keine Software.": "Recibe un agente listo para usar, no un software.",
  "Keine Mindestlaufzeit.": "Sin permanencia mínima.",
  "Was den Unterschied macht": "Lo que marca la diferencia",
  "Termine direkt im Gespräch": "Citas directamente en la conversación",
  "Der Agent prüft freie Zeiten und bucht, verschiebt oder storniert Termine direkt in Ihrem Kalender.": "El agente consulta los huecos libres y reserva, cambia o cancela citas directamente en su calendario.",
  "Direkt angebunden: Google Kalender, Cal.com, Calendly und GoHighLevel; Outlook und Branchen-Buchungssysteme über Automation oder Schnittstelle, sofern verfügbar. Bestätigung und Erinnerung per SMS oder E-Mail.": "Conexión directa: Google Calendar, Cal.com, Calendly y GoHighLevel; Outlook y sistemas de reserva sectoriales mediante automatización o API, si está disponible. Confirmación y recordatorio por SMS o correo electrónico.",
  "Antworten aus Ihren Inhalten": "Respuestas basadas en su contenido",
  "Der Agent beantwortet Fragen mit Ihrer Website, Preisliste und Ihren Dokumenten, statt zu raten.": "El agente responde con su sitio web, su lista de precios y sus documentos, en lugar de adivinar.",
  "Plattformwerte: bis 500 Webseiten mit automatischem Einlesen, 25 Dateien à 50 MB (PDF, Word, Excel, Bilder u. a.) und eigene Textbausteine. Tabellen und Überschriften werden sauber zerlegt, der Abruf ist im Transkript sichtbar, und Wissensdatenbanken lassen sich einzelnen Gesprächsschritten zuweisen.": "Valores de la plataforma: hasta 500 páginas web con lectura automática, 25 archivos de 50 MB cada uno (PDF, Word, Excel, imágenes, etc.) y fragmentos de texto propios. Tablas y títulos se dividen limpiamente, cada consulta queda visible en la transcripción y las bases de conocimiento pueden asignarse a pasos concretos de la conversación.",
  "Mehrsprachig mit automatischer Erkennung": "Multilingüe con detección automática",
  "Der Agent erkennt die Sprache Ihrer Kunden und antwortet darin, natürlich auch auf Deutsch.": "El agente reconoce el idioma de sus clientes y responde en él, también en español, por supuesto.",
  "Plattformwert: 55 Sprachen, darunter Deutsch, Französisch, Italienisch und Englisch. Sprachen sind pro Agent einzeln wählbar, ein Sprachwechsel mitten im Gespräch ist mit passenden Erkennungsanbietern möglich; einsprachige Agenten erkennen am genauesten.": "Valor de la plataforma: 55 idiomas, entre ellos alemán, francés, italiano e inglés. Los idiomas se eligen por agente; el cambio de idioma en mitad de la conversación es posible con los proveedores de reconocimiento adecuados, y los agentes monolingües reconocen con mayor precisión.",
  "Erinnert sich an Stammkunden": "Recuerda a los clientes habituales",
  "Meldet sich ein Kunde erneut, weiss der Agent, worum es beim letzten Mal ging.": "Cuando un cliente vuelve a contactar, el agente sabe de qué se trató la última vez.",
  "Kurzakte pro Kontakt (bis 2.000 Zeichen) wird nach Anrufen und SMS-Chats fortgeschrieben und ist für mehrere Agenten lesbar; bekannte Angaben müssen nicht neu erfragt werden. Die Speicherung lässt sich abschalten.": "Una ficha breve por contacto (hasta 2.000 caracteres) se actualiza tras llamadas y chats por SMS y la pueden leer varios agentes; no hace falta volver a preguntar lo que ya se sabe. El almacenamiento puede desactivarse.",
  "Haben Sie Freitag noch etwas frei?": "¿Le queda algo libre el viernes?",
  "Ja, um 10:00 oder 15:30 Uhr. Was passt Ihnen?": "Sí, a las 10:00 o a las 15:30. ¿Qué le viene mejor?",
  "Kalender · Fr 15:30 gebucht": "Calendario · reservado vie. 15:30",
  "Was kostet eine Gesichtsbehandlung?": "¿Cuánto cuesta un tratamiento facial?",
  "Die klassische Behandlung kostet {{m:95}} und dauert 60 Minuten.": "El tratamiento clásico cuesta {{m:95}} y dura 60 minutos.",
  "Quelle · Preisliste.pdf": "Fuente · Lista-de-precios.pdf",
  "Aus Ihrer Preisliste": "De su lista de precios",
  "Do you have a room for two nights?": "Do you have a room for two nights?",
  "Yes, from Friday. Shall I hold a double room for you?": "Yes, from Friday. Shall I hold a double room for you?",
  "Sprache erkannt · Englisch": "Idioma detectado · inglés",
  "Antwort in Kundensprache": "Respuesta en el idioma del cliente",
  "Hallo, hier ist Frau Keller.": "Hola, soy la señora Keller.",
  "Schön, von Ihnen zu hören. Wieder Balayage wie im März?": "Encantados de saber de usted. ¿Otra vez balayage, como en marzo?",
