  "Rufnummern für ein- und ausgehende Anrufe, auch für Deutschland, Österreich und die Schweiz, plus SMS in beide Richtungen.": "Números para llamadas entrantes y salientes, también para Alemania, Austria y Suiza, además de SMS en ambos sentidos.",
