  "Einrichtung + laufende Kosten": "Configuración + costes recurrentes",
  "Kumulierter Nutzen und Kosten über 12 Monate": "Beneficio y costes acumulados en 12 meses",
  "Annahmen: 4,33 Wochen pro Monat, 8-Stunden-Arbeitstag. Kosten mit der einmaligen Einrichtung am unteren Ende der Spanne (Voice {{p:voice-agent.setupMin}}, Chat {{p:chatbot.setupMin}}, Social {{p:social-media.setupMin}}) plus laufende Kosten: beim Voice Agent {{p:voice-agent.monthly}} Grundgebühr pro Monat und 4 Gesprächsminuten pro Anruf zu {{p:voice-agent.perUnit}}, 14 Nachrichten pro Chat und 40 Nachrichten pro Social-Media-Stunde zu je {{p:chatbot.perUnit}}. Gerettete Aufträge rechnen wir vorsichtig: nur unbeantwortete Anrufe, davon 30 % mit Abschluss, und nur wenn der Voice Agent ausgewählt ist. Alle Werte sind Schätzungen und keine Garantie.": "Supuestos: 4,33 semanas al mes, jornada de 8 horas. Costes con la configuración única en el extremo inferior del rango (Voice {{p:voice-agent.setupMin}}, Chat {{p:chatbot.setupMin}}, Social {{p:social-media.setupMin}}) más los costes recurrentes: en el Voice Agent, {{p:voice-agent.monthly}} de cuota base al mes y 4 minutos de llamada por llamada a {{p:voice-agent.perUnit}}; 14 mensajes por chat y 40 mensajes por hora de redes sociales, a {{p:chatbot.perUnit}} cada uno. Los encargos recuperados los calculamos con prudencia: solo llamadas sin respuesta, de ellas un 30 % con cierre, y solo si está seleccionado el Voice Agent. Todos los valores son estimaciones, sin garantía.",
