  "FAQ": "Preguntas frecuentes",
  "Fragen zu den Preisen": "Preguntas sobre los precios",
  "Wovon hängt der Preis ab?": "¿De qué depende el precio?",
  "Von Anbindungen, Sprachen und Standorten. Nach dem Erstgespräch gilt ein Festpreis.": "De las integraciones, los idiomas y las ubicaciones. Tras la primera conversación, se aplica un precio cerrado.",
  "Was kostet der Verbrauch?": "¿Cuánto cuesta el consumo?",
  "Ein Anruf von vier Minuten {{p:voice-agent.perUnit*4}}, ein Chat mit 14 Nachrichten rund {{p:chatbot.perUnit*14~2}}.": "Una llamada de cuatro minutos, {{p:voice-agent.perUnit*4}}; un chat de 14 mensajes, unos {{p:chatbot.perUnit*14~2}}.",
  "Gibt es eine Grundgebühr?": "¿Hay una cuota base?",
  "Nur beim Voice Agent: {{p:voice-agent.monthly}} pro Monat für Rufnummer und Betrieb. Die Website kostet {{p:website.monthly}} pro Monat für Hosting und Pflege.": "Solo en el Voice Agent: {{p:voice-agent.monthly}} al mes por el número de teléfono y el servicio. El sitio web cuesta {{p:website.monthly}} al mes por alojamiento y mantenimiento.",
  "Gibt es eine Mindestlaufzeit?": "¿Hay permanencia mínima?",
  "Nein. Kündbar zum Monatsende, ohne Restzahlung.": "No. Cancelable a fin de mes, sin pagos pendientes.",
  "Wie genau ist der Rechner?": "¿Qué precisión tiene la calculadora?",
  "Er zeigt Richtwerte. Die tatsächliche Wirkung kann abweichen.": "Muestra valores orientativos. El efecto real puede variar.",
