  "Kostenlos": "Gratis",
  "Haben Sie morgen um 10 Uhr frei?": "¿Tienen hueco mañana a las 10:00?",
  "Ja, 10 Uhr ist frei. Darf ich Ihren Namen notieren?": "Sí, a las 10:00 hay hueco. ¿Me dice su nombre?",
