  "Annahmen: 4,33 Wochen pro Monat, 8-Stunden-Arbeitstag. Kosten mit der einmaligen Einrichtung am unteren Ende der Spanne (Voice {{p:voice-agent.setupMin}}, Chat {{p:chatbot.setupMin}}, Social {{p:social-media.setupMin}}) plus laufende Kosten: beim Voice Agent {{p:voice-agent.monthly}} Grundgebühr pro Monat und 4 Gesprächsminuten pro Anruf zu {{p:voice-agent.perUnit}}, 14 Nachrichten pro Chat und 40 Nachrichten pro Social-Media-Stunde zu je {{p:chatbot.perUnit}}.": "Supuestos: 4,33 semanas al mes y jornada de 8 horas. Costes con la configuración única en el extremo inferior del rango (Voice {{p:voice-agent.setupMin}}, Chat {{p:chatbot.setupMin}}, Social {{p:social-media.setupMin}}) más los costes recurrentes: para el Voice Agent, {{p:voice-agent.monthly}} de cuota base al mes y 4 minutos de llamada por llamada a {{p:voice-agent.perUnit}}; 14 mensajes por chat y 40 mensajes por hora de redes sociales a {{p:chatbot.perUnit}} cada uno.",
  "Gerettete Aufträge rechnen wir vorsichtig: nur unbeantwortete Anrufe, davon 30 % mit Abschluss, und nur wenn der Voice Agent ausgewählt ist. Alle Werte sind Schätzungen und keine Garantie.": "Calculamos los encargos recuperados con prudencia: solo llamadas no atendidas, de las que un 30 % se cierra, y solo si el Voice Agent está seleccionado. Todos los valores son estimaciones, no una garantía.",
