  "Website: Vercel Inc., USA<br>KI-Agenten (Telefon und Chat): Retell AI, Inc., USA": "Sitio web: Vercel Inc., EE. UU.<br>Agentes de IA (teléfono y chat): Retell AI, Inc., EE. UU.",
